from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
names = ["START_HERE_FOR_CODEX.md", "2026-09-11-amanda-tfg-bim-agent-design.md", "2026-09-11-amanda-tfg-bim-agent-COMBINED-plan.md", "PLAN_SELF_REVIEW.md", "docs/notes/2026-09-15-revisao-planos-handoff.md"]
texts = {n:(ROOT/n).read_text(encoding="utf-8") for n in names}

def change(name, old, new):
    if old not in texts[name]:
        raise ValueError(f"Target missing in {name}: {old[:90]}")
    texts[name] = texts[name].replace(old,new)

